        if("range".equals(action)||"precision".equals(action)){JSONArray axes=((JSONObject)engine.command("inspect")).getJSONArray("axes");JSONObject axis=null;for(int i=0;i<axes.length();i++)if("comparison-B".equals(axes.getJSONObject(i).getString("id")))axis=axes.getJSONObject(i);if(axis==null)throw new IllegalStateException("Missing comparison axis");JSONObject patch=new JSONObject();if("range".equals(action))patch.put("range",axis.isNull("range")?new JSONArray().put(2000).put(2240):JSONObject.NULL);else patch.put("precision",axis.getInt("precision")==0?3:0);engine.command("setAxis","comparison-B",patch);
        }else{JSONObject result=(JSONObject)engine.invoke("nativeComparisonAction",action,chartWidth(),chartHeight(),"load".equals(action)&&savedComparison!=null?savedComparison:JSONObject.NULL);if("save".equals(action))savedComparison=result.getString("savedDocument");if("setup".equals(action)){comparisonActive=true;savedComparison=null;}}
